BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (100::BIGINT, 'Caracterización es un curso muy interesante, el profe sabe mucho, pero se va por las ramas y sus clases terminan siendo muy largas. Tiene muchos proyectos que aveces le cuesta un poco centrarse en el curso, mañana se entregan actas y aún no entrega calificaciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '35de4b68b961f092c08f99a3952620c4955822a9fdc030962882599cd3838740'::TEXT, ARRAY[2770]::BIGINT[]),
    (100::BIGINT, 'Honestamente, sus clases me parecieron aburridas. La metalurgia es preciosa, pero el encuentra la forma de aburrirla un poco. Sus examenes son un poco complicados. Muchos éxitos si llevan con el'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '49805444267c206b26e25053d2eb841b667cdf753adebeb2c8cb528230238a8c'::TEXT, ARRAY[2752]::BIGINT[]),
    (100::BIGINT, 'Buen profe, sabe mucho, sus clases son demasiado largas pero se aprende mucho. Aproveche cuando van a laboratorios ya que es algo que no se ve siempre. Exigente con los informes y las investigaciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6e4ed37280a5364880aaae3b163734b04496cefef6d9768677f27044d5dbbeb3'::TEXT, ARRAY[2770]::BIGINT[]),
    (100::BIGINT, 'Aleaciones: el profe se esfuerza en explicar, se distrae aveces, pero se nota que sabe de lo que está hablando. Es especial en las exposiciones y el examen presencial estuvo rudo, pero con las demás evaluaciones se recupera. Metro: no le gusta mucho dar el curso, pero se pasa y hasta con buena nota.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Pocos exámenes']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '22ee7c3a91fa377971031a0c3bdfe11f763e5a48f41644f0bb2734d01685c1b3'::TEXT, ARRAY[2752, 2748]::BIGINT[]),
    (100::BIGINT, 'Las clases son interesantes, y se realizan 2 exposiciones. La asistencia no es obligatoria para realizar las presentaciones.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8324f0b4efd0589c66849ab672d49ff645a9a394ac63453f6f9cf43206cf9746'::TEXT, ARRAY[4149]::BIGINT[]),
    (100::BIGINT, 'No se ve mucha materia con él, la primera clase solo habla de su experiencia en el tema. Pero a pesar de que se ve poco se tuvieron que hacer dos exposiciones de artículos en semanas seguidas y fue cansado, aún así calificó suave las exposiciones.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'e0476f4c60bb59c50d15df4cd737e567a275c3358e8c6e00650aa304d3b334d2'::TEXT, ARRAY[4149]::BIGINT[]),
    (100::BIGINT, 'No hay otra opción para el curso, pero es muy aburrido, como el 40% del curso fueron presentaciones de los estudiantes, y los exámenes y quices son bastante fuertes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '9f7f2b1ed82729aa8a22423b100e8ab4dde09517e33952fcdda565f611bd8a8c'::TEXT, ARRAY[2752]::BIGINT[]),
    (100::BIGINT, 'Muy buena gente pero terrible profesor, las clases mas aburridas del mundo pasando 10 diapositiva por minuto y tras de todo evalúa suuuper fuerte'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2bc37cad81c86a25e333d23ff53a599ed8b856abb71c39cb17d8539922d0623c'::TEXT, ARRAY[2752]::BIGINT[]),
    (100::BIGINT, 'El profe es muy desordenado, no domina en su totalidad la materia y se confunde bastante. Deja trabajos muy largos e individuales. Las clases son muy aburridas.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '110258da29b78de17903036c164ee33d31f4bc1ddb08dcdaba1499b59a9cc155'::TEXT, ARRAY[2752]::BIGINT[]),
    (100::BIGINT, 'Muy buen profe. Tiene toda la paciencia del mundo para explicar. Deja trabajos pesadillos pero exige la misma excelencia que da.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Inspirador']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '1c8fc3a3fcbc8772e7c21c1570509b48f55f0d297622815bf90cf1e5dbf36064'::TEXT, ARRAY[2752]::BIGINT[]),
    (100::BIGINT, 'Buen profe, si pone atención, si se aprende mucho. Se nota que sabe mucho de metodos. Las clases fueron pesadas, pero es porque la clase era de 5 a 9pm, pero el mae no tiene la culpa de eso. Si el asistente es Mauricio Castro Ureña, este preparado para que lo califique muy duro. Todo en parejas.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8867f571b8fc9a6075921cab81e076e11a26cf809f73d9757a643d26c50e420f'::TEXT, ARRAY[968]::BIGINT[]),
    (100::BIGINT, 'Que la clase sea de 4 horas es un asco, pero no es culpa de él. Califica duro, pero las tareas y los exámenes son muy parecidos a los ejercicios de la clase lo que los hace fáciles. Explicando es bueno y se nota su interés por enseñar. Meta con confianza con este profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '6488b40ce30366624a52b60babacb0a8b8d621c3b99632a9e4384768327ade6d'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'La clases son de 4 horas entonces se vuelve un poco aburridas pero el profesor explica muy bien, las tareas son en parejas y son un poco largas. Deja tareas programadas pero son sencillas y las prácticas en clases son muy fáciles. Los exámenes son de la materia vista en clase y a mano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'aab2da3abfcfe17c6c8d49edbcf4649e0704ffa8de76ae57795027f949225bc7'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Las clases son demasiadooooooooo aburridas, las tareas son fáciles pero a veces tiende a calificar un poco rudo y lls exámenes no son nada del otro mundo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '07d59269e1d5607b9a08e588a0cea9a5b739db3dc9408cef79d8979b992f9e20'::TEXT, ARRAY[968]::BIGINT[]),
    (100::BIGINT, 'Cualquier curso que pueda, llévelo con el Prof. Cubero.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'd3c23d0ef9b5a95e9eeadd28e3acf429fe76ae10b7778b0e49bfc0981bf06f92'::TEXT, ARRAY[2770]::BIGINT[]),
    (100::BIGINT, 'Muy bueno, contesta dudas, siempre está en consulta, aclara temas en clase. Con él se aprende a usar matlab, lo cual es de mucha ayuda en varias carreras. La clase teórica es media aburrida pero eso es debido a la naturaleza del curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-21T00:00:00+00:00'::TIMESTAMPTZ, '4f3b3d274cc88cd9f1b8d39a2ade2a82a15bfbf52ed55346aa9472b5da189a53'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Las tareas y trabajos no se entiende con facilidad.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a411afb101b5bc89d19ee99265b0f907bd818d1e1df218ade47f80b47fede105'::TEXT, ARRAY[968]::BIGINT[]),
    (100::BIGINT, 'Las clases son largas y aburridas, pero califica suave, las tareas son iguales a las anteriores, evalua lo visto en clase, no mas no menos. Curso facil de pasar'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2016-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8743a758204dd7f2a906492e74142112aa2ef408ab92e156e9fa05fe9811ba65'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Como profesor y persona es EXCELENTE, humilde, accesible..se preocupa por que se entienda lo que explica. Contesta correos! Recomendado 100%'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3702b2ee81bdc159f00d078b34442938fe14d7aac2a7c36a56f4189905b68fb3'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Es super atento y se preocupa porque los estudiantes entiendan. Las tareas que deja a pesar de ser largas son una buena herramienta de preparación para los exámenes. La clase de teoría es aburrida pero la parte práctica es entretenida. Se nota que le gusta enseñar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '04191d103d219266ed9b0767f1c9819450de802e22a355ca6f874bcedc4bac11'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '2c1b70209e8fbd2f4d940067b769a8b6c56a0fe03aa2446c8107542cb45a1811'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Aburrido, se pasa el curso fácil, con buena nota, solo es de entregar las tareas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'beb2b586acd51ac0a56f462fcf3cdca6586014b65615eedfa1291bf7c0ebafb0'::TEXT, ARRAY[968]::BIGINT[]),
    (100::BIGINT, 'Es el mejor profe de la Escuela. Hace cosas de investigación interesantes y permite que uno le ayude. Es un amor de persona, y esta guapillo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2016-04-26T00:00:00+00:00'::TIMESTAMPTZ, '35b39cb84b9512f50eaae9505d4eff7ef6bab8e249181a62be1a672a22850bb7'::TEXT, ARRAY[2770]::BIGINT[]),
    (100::BIGINT, 'Excelente profe, las tareas son en pareja y el curso no es programable. En consulta ayuda mucho y si uno no entiende explica todas las veces que usted necesite. SUPER RECOMENDADO. Las clases son muy aburridas, pero con las tareas lo prepara bien para los examenes los cuales son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '171d9f8c23ca6dd25096a9d317cca8083daf39e362e55cc39b3cdd22dde608cf'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[]),
    (100::BIGINT, 'Profe nuevo de materiales asi que no es corrompido :) Las clases pueden ser un bostezo, y los alumnos pierden interes... pero uno aprende estudiando para las tareas y quices que a veces son largos. Los examenes son maso, pero al final uno pasa con buena nota. Muy buena gente, humilde, y profesional.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c0dfc4868aa1fc690ac1d70e97e7ada157f55500ae1fa9d2675a7a8506694cfb'::TEXT, ARRAY[2957, 1679, 1680, 103]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
